8	} from "~/services/courseService";
9	import { getLessonById } from "~/services/lessonService";
10	import { getModuleById } from "~/services/moduleService";
11	import { getCurrentUserId } from "~/lib/session";
12	import { isUserEnrolled } from "~/services/enrollmentService";
13	import {
