59	const lessonParamsSchema = z.object({
60	  slug: z.string().min(1),
61	  lessonId: z.coerce.number().int(),
62	});
63	
64	const markCompleteSchema = z.object({
65	  intent: z.literal("mark-complete"),
66	});
