68	export function meta({ data: loaderData }: Route.MetaArgs) {
69	  const title = loaderData?.lesson?.title ?? "Lesson";
70	  const courseTitle = loaderData?.course?.title ?? "Course";
71	  return [{ title: `${title} — ${courseTitle} — Cadence` }];
72	}
