648	function CurriculumSidebar({
649	  course,
650	  curriculum,
651	  currentLessonId,
652	  lessonProgressMap,
653	  enrolled,
654	}: {
655	  course: { id: number; title: string; slug: string };
656	  curriculum: Array<{
657	    id: number;
658	    title: string;
659	    lessons: Array<{ id: number; title: string }>;
660	  }>;
661	  currentLessonId: number;
662	  lessonProgressMap: Record<number, string>;
663	  enrolled: boolean;
664	}) {
665	  // Find which module the current lesson belongs to
666	  const currentModuleId = curriculum.find((m) =>
667	    m.lessons.some((l) => l.id === currentLessonId)
668	  )?.id;
669	
670	  const [expandedModules, setExpandedModules] = useState<Set<number>>(() => {
671	    // Start with current module expanded
672	    const initial = new Set<number>();
673	    if (currentModuleId) initial.add(currentModuleId);
674	    return initial;
675	  });
676	
677	  function toggleModule(moduleId: number) {
678	    setExpandedModules((prev) => {
