              status === LessonProgressStatus.InProgress;
            const lessonBookmarked = bookmarkedLessonIds.has(l.id);

            return (
              <li key={l.id}>
                <Link
                  to={`/courses/${course.slug}/lessons/${l.id}`}
                  className={cn(
                    "flex items-center gap-2 rounded-md px-3 py-1.5 text-sm transition-colors",
                    isCurrent
                      ? "bg-primary/10 font-medium text-primary"
                      : "text-muted-foreground hover:bg-muted hover:text-foreground"
                  )}
                >
                  {enrolled ? (
                    isCompleted ? (
                      <CheckCircle2 className="size-3.5 shrink-0 text-green-500" />
                    ) : isInProgress ? (
                      <PlayCircle className="size-3.5 shrink-0 text-blue-500" />
                    ) : (
                      <Circle className="size-3.5 shrink-0" />
                    )
                  ) : (
                    <Circle className="size-3.5 shrink-0" />
                  )}
                  <span className="truncate">{l.title}</span>
                  {lessonBookmarked && (
                    <Bookmark className="ml-auto size-3.5 shrink-0 fill-amber-500 text-amber-500" />
                  )}
                </Link>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
})}

